.card {
 font-family: arial;
 font-size: 20px;
 text-align: center;
 color: black;
 background-color: white;
}
.gr-title {
    background-color: #f6f7f9;
    border: 2px solid #4d81ed;
    text-align: center;
    margin-top: 10px;
    color: #4d81ed;
    font-size: 18px;
    padding: 20px;
}
.gr-use-synopsis {
    color: #000000AA;
    line-height: 32px;
    font-size: 16px;
    background-color: #f6f7f9;
    padding: 16px;
}

.gr-use-note {
    margin-top: 1em;
    background-color: #f6f7f9;
    padding: 16px;
    border-left: 3px solid #4d81ed;
    color: #3f3f40;
    line-height: 32px;
    padding-bottom: 10px;
}
.grm-example-container {
    padding: 16px;
    padding-left: 24px;
}
.example-index {
    display: block;
    float: left;
    line-height: 60px;
    color: rgba(0,0,0,.3);
}
.example-mean-word {
    color: grey;
    font-style: italic;
    padding-left: 1em;
    padding-top: 8px;
}
.example-word {
    color: rgba(196,19,19,1);
    padding-left: 1em;
    padding-top: 1em;
}
